// Strict whole-flyer 5bps screen: minimum X must advance on every even tick.
use fastflyer::{Flyer,Kind};use std::{env,fs::File,io::Write};
fn counts(f:&Flyer)->[usize;11]{let mut a=[0;11];for(_,b)in f.blocks(){if b.kind()!=Kind::PistonArm{a[b.kind() as usize]+=1;}}a}
fn main(){let args:Vec<_>=env::args().collect();let ticks:usize=args[2].parse().unwrap();let seeds:u64=args[3].parse().unwrap();let mut out=File::create(&args[4]).unwrap();writeln!(out,"seed,phase_x,phase_z,ticks,first_bad_tick,reason,distance,min_powered").unwrap();for seed in 0..seeds{for phase_x in [0,7,8,15]{let mut f=Flyer::load(&args[1]).unwrap();f.rng_state=seed;f.phase_x=phase_x;let x0=f.blocks().iter().map(|(p,_)|p.x).min().unwrap();let initial=counts(&f);let mut bad=0;let mut reason="pass";let mut x=x0;let mut minpowered=usize::MAX;let mut tdone=0;for t in 1..=ticks{let r=f.tick().unwrap();let bs=f.blocks();x=bs.iter().map(|(p,_)|p.x).min().unwrap();tdone=t;minpowered=minpowered.min(r.powered_pistons);if x-x0<(t/2) as i64{bad=t;reason="speed";break;}if counts(&f)!=initial{bad=t;reason="conservation";break;}if r.extensions_started!=1{bad=t;reason="extension_count";break;}}
writeln!(out,"{seed},{phase_x},{},{tdone},{bad},{reason},{},{minpowered}",f.phase_z,x-x0).unwrap();out.flush().unwrap();println!("seed={seed} phase_x={phase_x} ticks={tdone} bad={bad} reason={reason} distance={} min_powered={minpowered}",x-x0);}}}

